"""Reviewed NL -> SQL pairs for the Nordmark Dagligvaror demo.

`demo rq-check nordmark --snowflake` executes every pair against DuckDB and Snowflake and
writes build/reviewed-queries.csv. Queries registered with `source="Ali-TD"` run on the
federated Teradata connection (checked with `demo rq-check nordmark --domain`), are bound to
that connection when published and stay out of the eval set and the extractor's query library.
NL text must not contain commas; SQL uses upper-case identifiers with double-quoted object names.
"""
from demo_creator.reviewed_queries import Registry

rq = Registry()
add = rq.add

# ---------------------------------------------------------------- lookups / basics
add("Which banners does Nordmark operate and what is each one's format and positioning?",
    'SELECT BANNER_NAME, STORE_FORMAT, POSITIONING, LOYALTY_PROGRAM, ACQUIRED_DATE, PRICE_INDEX, TARGET_GP_PCT FROM "BANNERS" ORDER BY BANNER_NAME')
add("How many stores do we have by banner and region?",
    'SELECT BANNER, REGION, COUNT(*) AS STORES FROM "STORES" WHERE STORE_STATUS = \'OPEN\' GROUP BY BANNER, REGION ORDER BY BANNER, REGION')
add("Show the store master record for Grosshallen Västerhamn.",
    'SELECT S.STORE_ID, S.STORE_NAME, S.BANNER, S.REGION, S.CITY, S.CATCHMENT_TYPE, S.PEER_CLUSTER, S.SALES_AREA_SQM, S.OPENED_DATE, S.ACQUIRED_DATE, S.STORE_MANAGER, N.POPULATION_2KM, N.HOUSEHOLDS_2KM, N.MEDIAN_INCOME_KSEK, N.COMPETITOR_COUNT_2KM, N.NEAREST_COMPETITOR_KM, N.CATCHMENT_POTENTIAL_MSEK FROM "STORES" AS S JOIN "NEIGHBORHOODS" AS N ON N.NEIGHBORHOOD_ID = S.NEIGHBORHOOD_ID WHERE S.STORE_NAME = \'Grosshallen Västerhamn\'')
add("Which stores were closed or converted to another banner?",
    'SELECT STORE_NAME, BANNER, REGION, CITY, CLOSED_DATE, CONVERTED_TO_BANNER, STORE_STATUS FROM "STORES" WHERE CLOSED_DATE IS NOT NULL ORDER BY CLOSED_DATE')
add("What is the definition and business owner of each metric in the data dictionary?",
    'SELECT TABLE_NAME, COLUMN_NAME, DESCRIPTION, METRIC_FORMULA, BUSINESS_OWNER, SOURCE_SYSTEM FROM "DATA_DICTIONARY" ORDER BY TABLE_NAME, COLUMN_NAME')
add("Which product categories do we range and which are non-food?",
    'SELECT CATEGORY_NAME, DEPARTMENT, IS_FRESH, IS_NONFOOD, SOLD_IN_BANNERS, TARGET_GP_PCT, CATEGORY_MANAGER FROM "PRODUCT_CATEGORIES" ORDER BY DEPARTMENT, CATEGORY_NAME')

# ---------------------------------------------------------------- level 1: key KPIs
add("What were group net sales and gross margin for the last 12 months by banner?",
    'SELECT BANNER, SUM(NET_SALES_SEK) AS NET_SALES_SEK, SUM(GROSS_PROFIT_SEK) AS GROSS_PROFIT_SEK, ROUND(SUM(GROSS_PROFIT_SEK) / NULLIF(SUM(NET_SALES_SEK), 0), 4) AS GP_PCT, SUM(TRANSACTIONS) AS TRANSACTIONS, ROUND(SUM(NET_SALES_SEK) / NULLIF(SUM(TRANSACTIONS), 0), 2) AS AVG_BASKET_SEK FROM "V_BANNER_KPI_MONTHLY" WHERE MONTH_START_DATE >= DATE \'2025-10-01\' GROUP BY BANNER ORDER BY NET_SALES_SEK DESC')
add("Show monthly net sales and like-for-like growth by banner for the last 12 months.",
    'SELECT MONTH_START_DATE, BANNER, NET_SALES_SEK, ROUND(LFL_GROWTH_PCT, 4) AS LFL_GROWTH_PCT, ROUND(GP_PCT, 4) AS GP_PCT, ROUND(AVG_BASKET_SEK, 2) AS AVG_BASKET_SEK FROM "V_BANNER_KPI_MONTHLY" WHERE MONTH_START_DATE >= DATE \'2025-10-01\' ORDER BY MONTH_START_DATE, BANNER')
add("What is the like-for-like sales growth of each banner over the rolling 12 months?",
    'SELECT BANNER, SUM(SALES_R12_SEK) AS SALES_R12_SEK, SUM(SALES_PRIOR_R12_SEK) AS SALES_PRIOR_R12_SEK, ROUND(SUM(SALES_R12_SEK) / NULLIF(SUM(SALES_PRIOR_R12_SEK), 0) - 1, 4) AS LFL_GROWTH_PCT, ROUND(SUM(TRANSACTIONS_R12) * 1.0 / NULLIF(SUM(TRANSACTIONS_PRIOR_R12), 0) - 1, 4) AS TRANSACTIONS_CHANGE_PCT, ROUND((SUM(SALES_R12_SEK) / NULLIF(SUM(TRANSACTIONS_R12), 0)) / NULLIF(SUM(SALES_PRIOR_R12_SEK) / NULLIF(SUM(TRANSACTIONS_PRIOR_R12), 0), 0) - 1, 4) AS BASKET_CHANGE_PCT FROM "V_STORE_GAP_DECOMPOSITION" GROUP BY BANNER ORDER BY LFL_GROWTH_PCT')
add("What are quarterly EBIT and EBIT margin by banner?",
    'SELECT QUARTER_LABEL, BANNER, SUM(NET_SALES_SEK) AS NET_SALES_SEK, SUM(EBIT_SEK) AS EBIT_SEK, ROUND(SUM(EBIT_SEK) / NULLIF(SUM(NET_SALES_SEK), 0), 4) AS EBIT_PCT FROM "V_BANNER_KPI_MONTHLY" GROUP BY QUARTER_LABEL, BANNER ORDER BY QUARTER_LABEL, BANNER')
add("How did Grosshallen's quarterly EBIT develop since the acquisition?",
    'SELECT QUARTER_LABEL, SUM(NET_SALES_SEK) AS NET_SALES_SEK, SUM(GROSS_PROFIT_SEK) AS GROSS_PROFIT_SEK, SUM(OPERATING_COSTS_SEK) AS OPERATING_COSTS_SEK, SUM(EBIT_SEK) AS EBIT_SEK, ROUND(SUM(EBIT_SEK) / NULLIF(SUM(NET_SALES_SEK), 0), 4) AS EBIT_PCT, ROUND(SUM(LABOUR_COST_SEK) / NULLIF(SUM(NET_SALES_SEK), 0), 4) AS LABOUR_COST_PCT FROM "V_BANNER_KPI_MONTHLY" WHERE BANNER = \'Grosshallen\' AND MONTH_START_DATE >= DATE \'2025-01-01\' GROUP BY QUARTER_LABEL ORDER BY QUARTER_LABEL')
add("Which stores had the highest net sales in September 2026?",
    'SELECT STORE_NAME, BANNER, REGION, NET_SALES_SEK, TRANSACTIONS, ROUND(AVG_BASKET_SEK, 2) AS AVG_BASKET_SEK, ROUND(GP_PCT, 4) AS GP_PCT FROM "V_KPI_STORE_MONTHLY" WHERE MONTH_START_DATE = DATE \'2026-09-01\' ORDER BY NET_SALES_SEK DESC LIMIT 20')
add("What is the average basket and transaction count by banner for the last 12 months?",
    'SELECT BANNER, SUM(TRANSACTIONS) AS TRANSACTIONS, ROUND(SUM(NET_SALES_SEK) / NULLIF(SUM(TRANSACTIONS), 0), 2) AS AVG_BASKET_SEK, ROUND(SUM(LOYALTY_SALES_SHARE * NET_SALES_SEK) / NULLIF(SUM(NET_SALES_SEK), 0), 4) AS LOYALTY_SALES_SHARE FROM "V_BANNER_KPI_MONTHLY" WHERE MONTH_START_DATE >= DATE \'2025-10-01\' GROUP BY BANNER ORDER BY BANNER')
add("Which categories had the most sales and the best margin in the last 13 weeks by banner?",
    'SELECT BANNER, CATEGORY_NAME, SUM(NET_SALES_13W_SEK) AS NET_SALES_SEK, ROUND(SUM(NET_SALES_13W_SEK) / NULLIF(SUM(NET_SALES_LY13_SEK), 0) - 1, 4) AS SALES_GROWTH_PCT, ROUND(SUM(OSA_PCT * NET_SALES_13W_SEK) / NULLIF(SUM(NET_SALES_13W_SEK), 0), 4) AS OSA_PCT FROM "V_AVAILABILITY_VS_SALES" GROUP BY BANNER, CATEGORY_NAME ORDER BY BANNER, NET_SALES_SEK DESC')
add("What are waste and markdown rates by banner over the rolling 12 months?",
    'SELECT S.BANNER, SUM(W.NET_SALES_SEK) AS NET_SALES_SEK, ROUND(SUM(W.WASTE_SEK) / NULLIF(SUM(W.NET_SALES_SEK), 0), 4) AS WASTE_RATE, ROUND(SUM(W.MARKDOWN_SEK) / NULLIF(SUM(W.NET_SALES_SEK), 0), 4) AS MARKDOWN_RATE, ROUND(SUM(W.ON_SHELF_AVAILABILITY_PCT * W.NET_SALES_SEK) / NULLIF(SUM(W.NET_SALES_SEK), 0), 4) AS OSA_PCT FROM "SALES_WEEKLY_STORE_CATEGORY" AS W JOIN "STORES" AS S ON S.STORE_ID = W.STORE_ID WHERE W.WEEK_START_DATE >= DATE \'2025-10-01\' GROUP BY S.BANNER ORDER BY S.BANNER')
add("How many active loyalty members and visits per member do we have by banner?",
    'SELECT BANNER, ROUND(SUM(ACTIVE_MEMBERS_R12)) AS ACTIVE_MEMBERS, SUM(VISITS_R12) AS VISITS, ROUND(SUM(VISITS_R12) / NULLIF(SUM(ACTIVE_MEMBERS_R12), 0), 2) AS VISITS_PER_MEMBER, ROUND(SUM(VISITS_R12) * 1.0 / NULLIF(SUM(VISITS_PRIOR_R12), 0) - 1, 4) AS VISITS_CHANGE_PCT FROM "V_LOYALTY_SEGMENT_TRENDS" GROUP BY BANNER ORDER BY BANNER')

# ---------------------------------------------------------------- level 2: what is driving performance
add("Which stores are declining the most over the rolling 12 months and is it transactions or basket?",
    'SELECT STORE_NAME, BANNER, REGION, ROUND(SALES_CHANGE_PCT, 4) AS SALES_CHANGE_PCT, SALES_CHANGE_SEK, ROUND(TRANSACTIONS_CHANGE_PCT, 4) AS TRANSACTIONS_CHANGE_PCT, ROUND(BASKET_CHANGE_PCT, 4) AS BASKET_CHANGE_PCT, TRANSACTIONS_EFFECT_SEK, BASKET_EFFECT_SEK, GROWTH_DRIVER FROM "V_STORE_GAP_DECOMPOSITION" ORDER BY SALES_CHANGE_PCT LIMIT 15')
add("Break down Grosshallen Västerhamn's sales change into transactions and basket effects.",
    'SELECT STORE_NAME, SALES_R12_SEK, SALES_PRIOR_R12_SEK, SALES_CHANGE_SEK, ROUND(SALES_CHANGE_PCT, 4) AS SALES_CHANGE_PCT, TRANSACTIONS_R12, TRANSACTIONS_PRIOR_R12, ROUND(TRANSACTIONS_CHANGE_PCT, 4) AS TRANSACTIONS_CHANGE_PCT, ROUND(BASKET_R12_SEK, 2) AS BASKET_R12_SEK, ROUND(BASKET_PRIOR_R12_SEK, 2) AS BASKET_PRIOR_R12_SEK, ROUND(BASKET_CHANGE_PCT, 4) AS BASKET_CHANGE_PCT, TRANSACTIONS_EFFECT_SEK, BASKET_EFFECT_SEK, GROWTH_DRIVER FROM "V_STORE_GAP_DECOMPOSITION" WHERE STORE_NAME = \'Grosshallen Västerhamn\'')
add("Which categories explain most of the sales change at Grosshallen Västerhamn in the last 13 weeks?",
    'SELECT CATEGORY_NAME, NET_SALES_13W_SEK, NET_SALES_LY13_SEK, NET_SALES_13W_SEK - NET_SALES_LY13_SEK AS SALES_CHANGE_SEK, ROUND(CATEGORY_SALES_GROWTH_PCT, 4) AS CATEGORY_SALES_GROWTH_PCT, ROUND(OSA_PCT, 4) AS OSA_PCT FROM "V_AVAILABILITY_VS_SALES" WHERE STORE_NAME = \'Grosshallen Västerhamn\' ORDER BY SALES_CHANGE_SEK')
add("How does Grosshallen Västerhamn compare with its peer cluster?",
    'SELECT STORE_NAME, PEER_CLUSTER, CLUSTER_STORES, ROUND(SALES_PER_SQM_SEK) AS SALES_PER_SQM_SEK, ROUND(CLUSTER_SALES_PER_SQM_SEK) AS CLUSTER_SALES_PER_SQM_SEK, ROUND(LFL_GROWTH_PCT, 4) AS LFL_GROWTH_PCT, ROUND(CLUSTER_LFL_GROWTH_PCT, 4) AS CLUSTER_LFL_GROWTH_PCT, ROUND(GP_PCT, 4) AS GP_PCT, ROUND(CLUSTER_GP_PCT, 4) AS CLUSTER_GP_PCT, ROUND(OSA_PCT, 4) AS OSA_PCT, ROUND(CLUSTER_OSA_PCT, 4) AS CLUSTER_OSA_PCT, ROUND(MARKDOWN_RATE, 4) AS MARKDOWN_RATE, ROUND(CLUSTER_MARKDOWN_RATE, 4) AS CLUSTER_MARKDOWN_RATE, ROUND(PL_SALES_SHARE, 4) AS PL_SALES_SHARE, ROUND(CLUSTER_PL_SALES_SHARE, 4) AS CLUSTER_PL_SALES_SHARE, ROUND(TRANSACTIONS_PER_HOUSEHOLD, 2) AS TRANSACTIONS_PER_HOUSEHOLD, ROUND(CLUSTER_TRANSACTIONS_PER_HOUSEHOLD, 2) AS CLUSTER_TRANSACTIONS_PER_HOUSEHOLD FROM "V_PEER_COMPARISON" WHERE STORE_NAME = \'Grosshallen Västerhamn\'')
add("Which stores in the Grosshallen Suburban family cluster have the biggest gaps to the cluster median?",
    'SELECT STORE_NAME, REGION, ROUND(LFL_GROWTH_GAP_PTS, 4) AS LFL_GROWTH_GAP_PTS, ROUND(GP_PCT_GAP_PTS, 4) AS GP_PCT_GAP_PTS, ROUND(OSA_GAP_PTS, 4) AS OSA_GAP_PTS, ROUND(MARKDOWN_RATE_GAP_PTS, 4) AS MARKDOWN_RATE_GAP_PTS, ROUND(PL_SALES_SHARE_GAP_PTS, 4) AS PL_SALES_SHARE_GAP_PTS, ROUND(SALES_PER_SQM_GAP_SEK) AS SALES_PER_SQM_GAP_SEK FROM "V_PEER_COMPARISON" WHERE PEER_CLUSTER = \'Grosshallen / Suburban family\' ORDER BY LFL_GROWTH_GAP_PTS')
add("Where are sales growing but margins getting worse?",
    'SELECT S.BANNER, C.CATEGORY_NAME, SUM(CASE WHEN W.WEEK_START_DATE >= DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END) AS SALES_R12_SEK, ROUND(SUM(CASE WHEN W.WEEK_START_DATE >= DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END) / NULLIF(SUM(CASE WHEN W.WEEK_START_DATE < DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END), 0) - 1, 4) AS SALES_GROWTH_PCT, ROUND(SUM(CASE WHEN W.WEEK_START_DATE >= DATE \'2025-10-01\' THEN W.GROSS_PROFIT_SEK ELSE 0 END) / NULLIF(SUM(CASE WHEN W.WEEK_START_DATE >= DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END), 0) - SUM(CASE WHEN W.WEEK_START_DATE < DATE \'2025-10-01\' THEN W.GROSS_PROFIT_SEK ELSE 0 END) / NULLIF(SUM(CASE WHEN W.WEEK_START_DATE < DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END), 0), 4) AS GP_PCT_CHANGE_PTS FROM "SALES_WEEKLY_STORE_CATEGORY" AS W JOIN "STORES" AS S ON S.STORE_ID = W.STORE_ID JOIN "PRODUCT_CATEGORIES" AS C ON C.CATEGORY_ID = W.CATEGORY_ID WHERE S.IS_LFL_COMPARABLE = TRUE AND W.WEEK_START_DATE >= DATE \'2024-10-07\' AND W.WEEK_START_DATE <= DATE \'2026-09-28\' GROUP BY S.BANNER, C.CATEGORY_NAME HAVING SUM(CASE WHEN W.WEEK_START_DATE >= DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END) > SUM(CASE WHEN W.WEEK_START_DATE < DATE \'2025-10-01\' THEN W.NET_SALES_SEK ELSE 0 END) ORDER BY GP_PCT_CHANGE_PTS')
add("Which promotions had strong sales but weak margins?",
    'SELECT PROMOTION_NAME, BANNER, CATEGORY_NAME, MECHANIC, DISCOUNT_PCT, START_DATE, END_DATE, PARTICIPATING_STORES, PROMO_SALES_SEK, ROUND(UPLIFT_PCT, 4) AS UPLIFT_PCT, ROUND(PROMO_GP_PCT, 4) AS PROMO_GP_PCT, ROUND(BASELINE_GP_PCT, 4) AS BASELINE_GP_PCT, ROUND(MARGIN_DILUTION_PTS, 4) AS MARGIN_DILUTION_PTS, INCREMENTAL_GP_SEK, PROMO_VERDICT FROM "V_PROMO_EFFECTIVENESS" WHERE PROMO_VERDICT = \'Strong sales weak margin\' ORDER BY MARGIN_DILUTION_PTS DESC')
add("How did the Sommarpris 2026 campaign perform?",
    'SELECT PROMOTION_NAME, BANNER, CATEGORY_NAME, MECHANIC, DISCOUNT_PCT, START_DATE, END_DATE, WEEKS, FUNDING_SOURCE, PARTICIPATING_STORES, PROMO_SALES_SEK, BASELINE_SALES_SEK, ROUND(UPLIFT_PCT, 4) AS UPLIFT_PCT, ROUND(PROMO_GP_PCT, 4) AS PROMO_GP_PCT, ROUND(BASELINE_GP_PCT, 4) AS BASELINE_GP_PCT, ROUND(MARGIN_DILUTION_PTS, 4) AS MARGIN_DILUTION_PTS, MARKDOWN_COST_SEK, INCREMENTAL_GP_SEK, UPLIFT_RANK, MARGIN_RANK_FROM_BOTTOM, PROMO_VERDICT FROM "V_PROMO_EFFECTIVENESS" WHERE PROMOTION_NAME = \'Sommarpris 2026\'')
add("Where do availability issues line up with weak sales?",
    'SELECT STORE_NAME, BANNER, REGION, ROUND(SUM(OSA_PCT * NET_SALES_13W_SEK) / NULLIF(SUM(NET_SALES_13W_SEK), 0), 4) AS DAIRY_BREAD_OSA_PCT, SUM(STOCKOUT_HOURS) AS STOCKOUT_HOURS, ROUND(MAX(STORE_LFL_GROWTH_PCT), 4) AS STORE_LFL_GROWTH_PCT FROM "V_AVAILABILITY_VS_SALES" WHERE CATEGORY_NAME IN (\'Dairy\', \'Bread & Bakery\') AND IS_LFL_COMPARABLE = TRUE GROUP BY STORE_NAME, BANNER, REGION HAVING SUM(OSA_PCT * NET_SALES_13W_SEK) / NULLIF(SUM(NET_SALES_13W_SEK), 0) < 0.94 ORDER BY DAIRY_BREAD_OSA_PCT')
add("What is the like-for-like growth of stores with Dairy and Bread availability below 94 percent compared with the rest?",
    'SELECT CASE WHEN T.OSA_PCT < 0.94 THEN \'OSA below 94 percent\' ELSE \'OSA 94 percent or better\' END AS AVAILABILITY_BAND, COUNT(*) AS STORES, ROUND(AVG(T.STORE_LFL_GROWTH_PCT), 4) AS AVG_STORE_LFL_GROWTH_PCT, ROUND(AVG(T.OSA_PCT), 4) AS AVG_OSA_PCT FROM (SELECT STORE_ID, SUM(OSA_PCT * NET_SALES_13W_SEK) / NULLIF(SUM(NET_SALES_13W_SEK), 0) AS OSA_PCT, MAX(STORE_LFL_GROWTH_PCT) AS STORE_LFL_GROWTH_PCT FROM "V_AVAILABILITY_VS_SALES" WHERE CATEGORY_NAME IN (\'Dairy\', \'Bread & Bakery\') AND IS_LFL_COMPARABLE = TRUE GROUP BY STORE_ID) AS T GROUP BY CASE WHEN T.OSA_PCT < 0.94 THEN \'OSA below 94 percent\' ELSE \'OSA 94 percent or better\' END ORDER BY AVAILABILITY_BAND')
add("Which customer segments are visiting less or spending less by banner?",
    'SELECT BANNER, SEGMENT, SUM(VISITS_R12) AS VISITS_R12, SUM(VISITS_PRIOR_R12) AS VISITS_PRIOR_R12, ROUND(SUM(VISITS_R12) * 1.0 / NULLIF(SUM(VISITS_PRIOR_R12), 0) - 1, 4) AS VISITS_CHANGE_PCT, ROUND(SUM(SPEND_R12_SEK) / NULLIF(SUM(SPEND_PRIOR_R12_SEK), 0) - 1, 4) AS SPEND_CHANGE_PCT FROM "V_LOYALTY_SEGMENT_TRENDS" GROUP BY BANNER, SEGMENT ORDER BY VISITS_CHANGE_PCT')
add("How have loyalty segments changed at Grosshallen Västerhamn?",
    'SELECT SEGMENT, ROUND(ACTIVE_MEMBERS_R12) AS ACTIVE_MEMBERS_R12, ROUND(ACTIVE_MEMBERS_CHANGE_PCT, 4) AS ACTIVE_MEMBERS_CHANGE_PCT, VISITS_R12, VISITS_PRIOR_R12, ROUND(VISITS_CHANGE_PCT, 4) AS VISITS_CHANGE_PCT, ROUND(SPEND_CHANGE_PCT, 4) AS SPEND_CHANGE_PCT, ROUND(VISITS_PER_MEMBER_R12, 2) AS VISITS_PER_MEMBER_R12, LAPSED_MEMBERS_R12 FROM "V_LOYALTY_SEGMENT_TRENDS" WHERE STORE_NAME = \'Grosshallen Västerhamn\' ORDER BY VISITS_CHANGE_PCT')

# ---------------------------------------------------------------- level 3: opportunity and action
add("Which stores are underperforming relative to their catchment potential?",
    'SELECT STORE_NAME, BANNER, REGION, CATCHMENT_TYPE, SALES_R12_SEK, CATCHMENT_POTENTIAL_MSEK, ROUND(POTENTIAL_INDEX, 3) AS POTENTIAL_INDEX, ROUND(CLUSTER_MEDIAN_INDEX, 3) AS CLUSTER_MEDIAN_INDEX, POTENTIAL_GAP_SEK, GAP_RANK_IN_BANNER, POTENTIAL_BAND, COMPETITOR_COUNT_2KM, DISCOUNT_COMPETITOR_FLAG FROM "V_CATCHMENT_POTENTIAL" WHERE POTENTIAL_BAND IN (\'Underperforming\', \'Below potential\') ORDER BY POTENTIAL_GAP_SEK DESC LIMIT 20')
add("Which Grosshallen store has the largest gap to its catchment potential in SEK?",
    'SELECT STORE_NAME, REGION, CITY, PEER_CLUSTER, SALES_R12_SEK, CATCHMENT_POTENTIAL_MSEK, ROUND(POTENTIAL_INDEX, 3) AS POTENTIAL_INDEX, ROUND(CLUSTER_MEDIAN_INDEX, 3) AS CLUSTER_MEDIAN_INDEX, POTENTIAL_GAP_SEK, POTENTIAL_BAND FROM "V_CATCHMENT_POTENTIAL" WHERE BANNER = \'Grosshallen\' ORDER BY POTENTIAL_GAP_SEK DESC LIMIT 5')
add("Which store formats perform best in each neighbourhood type?",
    'SELECT CATCHMENT_TYPE, BANNER, COUNT(*) AS STORES, ROUND(AVG(POTENTIAL_INDEX), 3) AS AVG_POTENTIAL_INDEX, ROUND(SUM(SALES_R12_SEK) / NULLIF(SUM(SALES_AREA_SQM), 0)) AS SALES_PER_SQM_SEK FROM "V_CATCHMENT_POTENTIAL" GROUP BY CATCHMENT_TYPE, BANNER ORDER BY CATCHMENT_TYPE, AVG_POTENTIAL_INDEX DESC')
add("Why does Grosshallen Nordstaden outperform Grosshallen Västerhamn with a similar catchment?",
    'SELECT P.STORE_NAME, C.CATCHMENT_TYPE, C.POPULATION_2KM, C.HOUSEHOLDS_2KM, C.MEDIAN_INCOME_KSEK, C.SHARE_FAMILIES, C.COMPETITOR_COUNT_2KM, C.NEAREST_COMPETITOR_KM, ROUND(C.POTENTIAL_INDEX, 3) AS POTENTIAL_INDEX, ROUND(P.LFL_GROWTH_PCT, 4) AS LFL_GROWTH_PCT, ROUND(P.GP_PCT, 4) AS GP_PCT, ROUND(P.OSA_PCT, 4) AS OSA_PCT, ROUND(P.MARKDOWN_RATE, 4) AS MARKDOWN_RATE, ROUND(P.WASTE_RATE, 4) AS WASTE_RATE, ROUND(P.PL_SALES_SHARE, 4) AS PL_SALES_SHARE, ROUND(P.AVG_BASKET_SEK, 2) AS AVG_BASKET_SEK, ROUND(P.TRANSACTIONS_PER_HOUSEHOLD, 2) AS TRANSACTIONS_PER_HOUSEHOLD FROM "V_PEER_COMPARISON" AS P JOIN "V_CATCHMENT_POTENTIAL" AS C ON C.STORE_ID = P.STORE_ID WHERE P.STORE_NAME IN (\'Grosshallen Västerhamn\', \'Grosshallen Nordstaden\') ORDER BY P.STORE_NAME')
add("What competitor events happened near Grosshallen Västerhamn?",
    'SELECT E.EVENT_DATE, E.COMPETITOR_NAME, E.COMPETITOR_FORMAT, E.EVENT_TYPE, E.DISTANCE_KM, E.ESTIMATED_SALES_IMPACT_PCT, E.NOTES FROM "COMPETITOR_EVENTS" AS E JOIN "STORES" AS S ON S.STORE_ID = E.STORE_ID WHERE S.STORE_NAME = \'Grosshallen Västerhamn\' ORDER BY E.EVENT_DATE')
add("How did Grosshallen Västerhamn's monthly sales and transactions develop before and after the Billigmat opening in March 2026?",
    'SELECT MONTH_START_DATE, NET_SALES_SEK, LY_NET_SALES_SEK, ROUND(SALES_GROWTH_PCT, 4) AS SALES_GROWTH_PCT, TRANSACTIONS, LY_TRANSACTIONS, ROUND(TRANSACTIONS_GROWTH_PCT, 4) AS TRANSACTIONS_GROWTH_PCT, ROUND(AVG_BASKET_SEK, 2) AS AVG_BASKET_SEK FROM "V_KPI_STORE_MONTHLY" WHERE STORE_NAME = \'Grosshallen Västerhamn\' AND MONTH_START_DATE >= DATE \'2025-10-01\' ORDER BY MONTH_START_DATE')
add("Which stores had competitor openings within 2 km and how did their sales change afterwards?",
    'SELECT S.STORE_NAME, S.BANNER, E.EVENT_DATE, E.COMPETITOR_NAME, E.DISTANCE_KM, E.ESTIMATED_SALES_IMPACT_PCT, ROUND(G.SALES_CHANGE_PCT, 4) AS SALES_CHANGE_R12_PCT, ROUND(G.TRANSACTIONS_CHANGE_PCT, 4) AS TRANSACTIONS_CHANGE_PCT FROM "COMPETITOR_EVENTS" AS E JOIN "STORES" AS S ON S.STORE_ID = E.STORE_ID LEFT JOIN "V_STORE_GAP_DECOMPOSITION" AS G ON G.STORE_ID = E.STORE_ID WHERE E.EVENT_TYPE = \'Opening\' AND E.DISTANCE_KM <= 2 ORDER BY G.SALES_CHANGE_PCT')
add("What is Grosshallen Västerhamn's private label share by category compared with Grosshallen Nordstaden?",
    'SELECT C.CATEGORY_NAME, ROUND(AVG(CASE WHEN S.STORE_NAME = \'Grosshallen Västerhamn\' THEN A.PL_SALES_SHARE END), 4) AS VASTERHAMN_PL_SHARE, ROUND(AVG(CASE WHEN S.STORE_NAME = \'Grosshallen Nordstaden\' THEN A.PL_SALES_SHARE END), 4) AS NORDSTADEN_PL_SHARE, ROUND(AVG(CASE WHEN S.STORE_NAME = \'Grosshallen Västerhamn\' THEN A.LISTED_SKUS END)) AS VASTERHAMN_LISTED_SKUS, ROUND(AVG(CASE WHEN S.STORE_NAME = \'Grosshallen Nordstaden\' THEN A.LISTED_SKUS END)) AS NORDSTADEN_LISTED_SKUS FROM "STORE_ASSORTMENT_MONTHLY" AS A JOIN "STORES" AS S ON S.STORE_ID = A.STORE_ID JOIN "PRODUCT_CATEGORIES" AS C ON C.CATEGORY_ID = A.CATEGORY_ID WHERE S.STORE_NAME IN (\'Grosshallen Västerhamn\', \'Grosshallen Nordstaden\') AND A.MONTH_START_DATE >= DATE \'2025-10-01\' GROUP BY C.CATEGORY_NAME ORDER BY C.CATEGORY_NAME')
add("What is the estimated sales upside if Grosshallen Västerhamn reached its cluster median potential index?",
    'SELECT STORE_NAME, SALES_R12_SEK, ROUND(POTENTIAL_INDEX, 3) AS POTENTIAL_INDEX, ROUND(CLUSTER_MEDIAN_INDEX, 3) AS CLUSTER_MEDIAN_INDEX, ROUND(CATCHMENT_POTENTIAL_MSEK * 1000000 * CLUSTER_MEDIAN_INDEX - SALES_R12_SEK) AS UPSIDE_TO_CLUSTER_MEDIAN_SEK, ROUND(CATCHMENT_POTENTIAL_MSEK * 1000000 * 0.75 - SALES_R12_SEK) AS UPSIDE_TO_075_INDEX_SEK FROM "V_CATCHMENT_POTENTIAL" WHERE STORE_NAME = \'Grosshallen Västerhamn\'')

# ---------------------------------------------------------------- non-food availability (Snowflake side of the federation beat)
add("Which import suppliers account for the most non-food lost sales at Grosshallen in the last 12 months?",
    'SELECT SUPPLIER_KEY, COUNT(DISTINCT STORE_ID) AS STORES, SUM(NET_SALES_SEK) AS NET_SALES_SEK, SUM(LOST_SALES_SEK) AS LOST_SALES_SEK, ROUND(SUM(LOST_SALES_SEK) / NULLIF(SUM(NET_SALES_SEK + LOST_SALES_SEK), 0), 4) AS LOST_SALES_SHARE, ROUND(SUM(OSA_PCT * (NET_SALES_SEK + LOST_SALES_SEK)) / NULLIF(SUM(NET_SALES_SEK + LOST_SALES_SEK), 0), 4) AS OSA_PCT, SUM(STOCKOUT_DAYS) AS STOCKOUT_DAYS FROM "V_NONFOOD_AVAILABILITY_BY_SUPPLIER" WHERE MONTH_START_DATE >= DATE \'2025-10-01\' GROUP BY SUPPLIER_KEY ORDER BY LOST_SALES_SEK DESC LIMIT 10')
add("What is the non-food availability and lost sales at Grosshallen Västerhamn by supplier?",
    'SELECT SUPPLIER_KEY, SUM(SKUS) AS SKU_MONTHS, SUM(NET_SALES_SEK) AS NET_SALES_SEK, SUM(LOST_SALES_SEK) AS LOST_SALES_SEK, ROUND(SUM(OSA_PCT * (NET_SALES_SEK + LOST_SALES_SEK)) / NULLIF(SUM(NET_SALES_SEK + LOST_SALES_SEK), 0), 4) AS OSA_PCT, SUM(STOCKOUT_DAYS) AS STOCKOUT_DAYS FROM "V_NONFOOD_AVAILABILITY_BY_SUPPLIER" WHERE STORE_NAME = \'Grosshallen Västerhamn\' AND MONTH_START_DATE >= DATE \'2025-10-01\' GROUP BY SUPPLIER_KEY ORDER BY LOST_SALES_SEK DESC')
add("Which non-food SKUs had the worst availability across Grosshallen stores in 2026?",
    'SELECT N.PRODUCT_KEY, N.SKU, N.PRODUCT_NAME, N.CATEGORY_NAME, N.BRAND, N.SUPPLIER_KEY, ROUND(SUM(A.ON_SHELF_AVAILABILITY_PCT * (A.NET_SALES_SEK + A.LOST_SALES_SEK)) / NULLIF(SUM(A.NET_SALES_SEK + A.LOST_SALES_SEK), 0), 4) AS OSA_PCT, SUM(A.LOST_SALES_SEK) AS LOST_SALES_SEK, SUM(A.STOCKOUT_DAYS) AS STOCKOUT_DAYS FROM "NONFOOD_AVAILABILITY_MONTHLY" AS A JOIN "NONFOOD_ASSORTMENT" AS N ON N.PRODUCT_KEY = A.PRODUCT_KEY WHERE A.MONTH_START_DATE >= DATE \'2026-01-01\' GROUP BY N.PRODUCT_KEY, N.SKU, N.PRODUCT_NAME, N.CATEGORY_NAME, N.BRAND, N.SUPPLIER_KEY ORDER BY LOST_SALES_SEK DESC LIMIT 25')

# ---------------------------------------------------------------- federated: the import-purchasing platform on Teradata (Ali-TD, database wisdomai)
add("Which import suppliers have the latest purchase-order deliveries?",
    "SELECT TOP 10 s.supplier_key, s.supplier_name, s.country, s.lead_time_days, s.on_time_rate, COUNT(*) AS po_lines, AVG(CAST(p.days_late AS DECIMAL(10,4))) AS avg_days_late, SUM(CASE WHEN p.po_status = 'Short-Received' THEN 1 ELSE 0 END) AS short_received_lines FROM wisdomai.RTL_FACT_PURCHASE_ORDER_LINE p JOIN wisdomai.RTL_DIM_SUPPLIER s ON s.supplier_key = p.supplier_key GROUP BY s.supplier_key, s.supplier_name, s.country, s.lead_time_days, s.on_time_rate ORDER BY avg_days_late DESC",
    source="Ali-TD")
add("Show the purchase-order performance of suppliers Sterling Trading and Frontier Trading and Lakeshore Industries by month in 2026.",
    "SELECT s.supplier_name, EXTRACT(YEAR FROM p.order_date) AS order_year, EXTRACT(MONTH FROM p.order_date) AS order_month, COUNT(*) AS po_lines, SUM(p.ordered_qty) AS ordered_qty, SUM(p.received_qty) AS received_qty, AVG(CAST(p.days_late AS DECIMAL(10,4))) AS avg_days_late, SUM(CASE WHEN p.po_status = 'Short-Received' THEN 1 ELSE 0 END) AS short_received_lines FROM wisdomai.RTL_FACT_PURCHASE_ORDER_LINE p JOIN wisdomai.RTL_DIM_SUPPLIER s ON s.supplier_key = p.supplier_key WHERE s.supplier_name IN ('Sterling Trading', 'Frontier Trading', 'Lakeshore Industries') AND p.order_date >= DATE '2026-01-01' GROUP BY s.supplier_name, EXTRACT(YEAR FROM p.order_date), EXTRACT(MONTH FROM p.order_date) ORDER BY s.supplier_name, order_year, order_month",
    source="Ali-TD")
add("Which open purchase orders are already late in the import-purchasing platform?",
    "SELECT TOP 50 p.po_number, p.order_date, p.expected_date, s.supplier_name, s.country, pr.product_name, pr.department, p.ordered_qty, p.po_status FROM wisdomai.RTL_FACT_PURCHASE_ORDER_LINE p JOIN wisdomai.RTL_DIM_SUPPLIER s ON s.supplier_key = p.supplier_key JOIN wisdomai.RTL_DIM_PRODUCT pr ON pr.product_key = p.product_key WHERE p.po_status = 'Open' AND p.expected_date < DATE '2026-09-30' ORDER BY p.expected_date",
    source="Ali-TD")
add("What are the supplier name country lead time and on-time rate for supplier keys 26 and 39 and 52?",
    "SELECT supplier_key, supplier_name, country, lead_time_days, on_time_rate, payment_terms, supplier_tier FROM wisdomai.RTL_DIM_SUPPLIER WHERE supplier_key IN (26, 39, 52) ORDER BY supplier_key",
    source="Ali-TD")

# ---------------------------------------------------------------- Revision 2: the Kampanjrapport (campaign performance and forecast accuracy)
GRID = ('SELECT VECKA_LABEL, KAMPANJ_NAMN, TAKTIK_TYP, NYCKEL, ARTIKEL_NAMN, KATEGORI, FARSKVARA, PLANERAD_KVANTITET, SALD_PROGNOS_CATBOOST, KOPT_PROGNOS_KEDJAN, FAKTISK_SALD, '
        'ROUND(PROGNOSFEL_CATBOOST_PCT, 4) AS PROGNOSFEL_CATBOOST_PCT, ROUND(PROGNOSFEL_KEDJAN_PCT, 4) AS PROGNOSFEL_KEDJAN_PCT '
        'FROM "V_KAMPANJRAPPORT" WHERE KEDJA = \'Kronmat\' AND VECKA_LABEL = \'2026-W36\' ORDER BY TAKTIK_TYP, KAMPANJ_NAMN, ARTIKEL_NAMN')
add("Show the Kampanjrapport for Kronmat week 2026-W36 with planned quantity both forecasts actual sold and forecast error by article.", GRID)
add("/kampanjrapport Kronmat 2026-W36", GRID, tags=("eval_only", "skill"))
add("Visa kampanjrapporten för Kronmat vecka 36 2026.", GRID, tags=("eval_only",))
add("What were the totals of the Kronmat campaigns in week 2026-W36 versus both forecasts?",
    'SELECT KEDJA, VECKA_LABEL, COUNT(*) AS ARTIKLAR, SUM(PLANERAD_KVANTITET) AS PLANERAD_KVANTITET, SUM(SALD_PROGNOS_CATBOOST) AS SALD_PROGNOS_CATBOOST, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, SUM(FAKTISK_SALD) AS FAKTISK_SALD, ROUND((SUM(SALD_PROGNOS_CATBOOST) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS PROGNOSFEL_CATBOOST_PCT, ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS PROGNOSFEL_KEDJAN_PCT FROM "V_KAMPANJRAPPORT" WHERE KEDJA = \'Kronmat\' AND VECKA_LABEL = \'2026-W36\' GROUP BY KEDJA, VECKA_LABEL')
add("Show forecast bias by tactic type for Kronmat in week 2026-W36.",
    'SELECT TAKTIK_TYP, SUM(ARTIKLAR) AS ARTIKLAR, SUM(FAKTISK_SALD) AS FAKTISK_SALD, SUM(SALD_PROGNOS_CATBOOST) AS SALD_PROGNOS_CATBOOST, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, ROUND((SUM(SALD_PROGNOS_CATBOOST) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_CATBOOST_PCT, ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_KEDJAN_PCT FROM "V_PROGNOSFEL_TAKTIK" WHERE KEDJA = \'Kronmat\' AND VECKA_LABEL = \'2026-W36\' GROUP BY TAKTIK_TYP ORDER BY BIAS_KEDJAN_PCT DESC')
add("Which campaigns ran in Kronmat in week 2026-W36 and what tactic did each use?",
    'SELECT KAMPANJ_ID, KAMPANJ_NAMN, TAKTIK_TYP_KOD, TAKTIK_TYP, TEMA, LEVERANS_FRAN, LEVERANS_TILL, KAMPANJ_START, KAMPANJ_SLUT, ANTAL_ARTIKLAR, ANSVARIG_PLANERARE, STATUS FROM "KAMPANJ" WHERE KEDJA = \'Kronmat\' AND VECKA_LABEL = \'2026-W36\' ORDER BY KAMPANJ_ID')
BIAS_13W = ('SELECT TAKTIK_TYP, SUM(ARTIKLAR) AS ARTIKEL_VECKOR, SUM(FAKTISK_SALD) AS FAKTISK_SALD, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, SUM(SALD_PROGNOS_CATBOOST) AS SALD_PROGNOS_CATBOOST, '
            'ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_KEDJAN_PCT, ROUND((SUM(SALD_PROGNOS_CATBOOST) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_CATBOOST_PCT, SUM(ABS_FEL_KEDJAN) AS ABS_FEL_KEDJAN '
            'FROM "V_PROGNOSFEL_TAKTIK" WHERE KALENDER_VECKA_ID BETWEEN 202627 AND 202639 GROUP BY TAKTIK_TYP ORDER BY BIAS_KEDJAN_PCT DESC')
add("Which tactic type has the highest forecast error over the last 13 campaign weeks?", BIAS_13W)
add("Vilken taktiktyp har störst prognosfel de senaste 13 kampanjveckorna?", BIAS_13W, tags=("eval_only",))
add("/prognosavvikelse Multiköp 3 för 2 last 13 weeks",
    'SELECT KEDJA, FARSKVARA, SUM(ARTIKLAR) AS ARTIKEL_VECKOR, SUM(FAKTISK_SALD) AS FAKTISK_SALD, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_KEDJAN_PCT, SUM(OVERPROGNOS_KVANTITET) AS OVERPROGNOS_KVANTITET FROM "V_PROGNOSFEL_TAKTIK" WHERE TAKTIK_TYP = \'Multiköp 3 för 2\' AND KALENDER_VECKA_ID BETWEEN 202627 AND 202639 GROUP BY KEDJA, FARSKVARA ORDER BY BIAS_KEDJAN_PCT DESC',
    tags=("eval_only", "skill"))
add("How much of the absolute forecast error comes from perishables versus dry goods over the last 13 campaign weeks?",
    'SELECT FARSKVARA, SUM(ARTIKLAR) AS ARTIKEL_VECKOR, SUM(FAKTISK_SALD) AS FAKTISK_SALD, SUM(ABS_FEL_KEDJAN) AS ABS_FEL_KEDJAN, ROUND(SUM(ABS_FEL_KEDJAN) / NULLIF((SELECT SUM(ABS_FEL_KEDJAN) FROM "V_PROGNOSFEL_TAKTIK" WHERE KALENDER_VECKA_ID BETWEEN 202627 AND 202639), 0), 4) AS SHARE_OF_ABS_ERROR, ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_KEDJAN_PCT FROM "V_PROGNOSFEL_TAKTIK" WHERE KALENDER_VECKA_ID BETWEEN 202627 AND 202639 GROUP BY FARSKVARA ORDER BY FARSKVARA DESC')
add("Which articles were most over-forecast by the chain plan in 2026?",
    'SELECT ARTIKEL_ID, ARTIKEL_NAMN, KATEGORI, FARSKVARA, COUNT(*) AS KAMPANJVECKOR, SUM(FAKTISK_SALD) AS FAKTISK_SALD, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, SUM(OVERPROGNOS_KVANTITET) AS OVERPROGNOS_KVANTITET, ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS PROGNOSFEL_KEDJAN_PCT FROM "V_KAMPANJRAPPORT" WHERE AR_AVSLUTAD AND KALENDER_VECKA_ID >= 202601 GROUP BY ARTIKEL_ID, ARTIKEL_NAMN, KATEGORI, FARSKVARA ORDER BY OVERPROGNOS_KVANTITET DESC LIMIT 10')
add("What is the forecast bias trend by week for Kronmat Multiköp campaigns in 2026?",
    'SELECT VECKA_LABEL, SUM(ARTIKLAR) AS ARTIKLAR, SUM(FAKTISK_SALD) AS FAKTISK_SALD, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, ROUND((SUM(KOPT_PROGNOS_KEDJAN) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_KEDJAN_PCT, ROUND((SUM(SALD_PROGNOS_CATBOOST) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS BIAS_CATBOOST_PCT FROM "V_PROGNOSFEL_TAKTIK" WHERE KEDJA = \'Kronmat\' AND TAKTIK_TYP = \'Multiköp 3 för 2\' AND KALENDER_VECKA_ID >= 202601 GROUP BY VECKA_LABEL ORDER BY VECKA_LABEL')
add("Which Grosshallen stores have the largest campaign forecast deviation over the last 12 months?",
    'SELECT STORE_NAME, REGION, PEER_CLUSTER, COUNT(*) AS KAMPANJVECKOR, SUM(PROGNOS_KVANTITET) AS PROGNOS_KVANTITET, SUM(FAKTISK_SALD) AS FAKTISK_SALD, ROUND((SUM(PROGNOS_KVANTITET) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS AVVIKELSE_PCT, MAX(CASE WHEN HAR_KONKURRENTHANDELSE_90D THEN 1 ELSE 0 END) AS KONKURRENTHANDELSE FROM "V_KAMPANJ_BUTIK_AVVIKELSE" WHERE BANNER = \'Grosshallen\' AND VECKA_START >= DATE \'2025-10-01\' GROUP BY STORE_NAME, REGION, PEER_CLUSTER ORDER BY AVVIKELSE_PCT DESC LIMIT 10')
add("How did Grosshallen Västerhamn's campaign forecast deviation change before and after the Billigmat opening in March 2026?",
    'SELECT CASE WHEN VECKA_START >= DATE \'2026-03-16\' THEN \'After opening\' ELSE \'Before opening\' END AS PERIOD, COUNT(*) AS KAMPANJVECKOR, SUM(PROGNOS_KVANTITET) AS PROGNOS_KVANTITET, SUM(FAKTISK_SALD) AS FAKTISK_SALD, ROUND((SUM(PROGNOS_KVANTITET) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0), 4) AS AVVIKELSE_PCT FROM "V_KAMPANJ_BUTIK_AVVIKELSE" WHERE STORE_NAME = \'Grosshallen Västerhamn\' AND VECKA_START >= DATE \'2025-10-01\' GROUP BY CASE WHEN VECKA_START >= DATE \'2026-03-16\' THEN \'After opening\' ELSE \'Before opening\' END ORDER BY PERIOD')
add("How does Grosshallen Västerhamn's campaign forecast deviation compare with the median store of its peer cluster?",
    'SELECT T.STORE_NAME, T.PEER_CLUSTER, ROUND(T.AVVIKELSE_PCT, 4) AS AVVIKELSE_PCT, ROUND(M.CLUSTER_MEDIAN_PCT, 4) AS CLUSTER_MEDIAN_PCT, ROUND(T.AVVIKELSE_PCT - M.CLUSTER_MEDIAN_PCT, 4) AS GAP_PTS FROM (SELECT STORE_NAME, PEER_CLUSTER, (SUM(PROGNOS_KVANTITET) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0) AS AVVIKELSE_PCT FROM "V_KAMPANJ_BUTIK_AVVIKELSE" WHERE VECKA_START >= DATE \'2025-10-01\' GROUP BY STORE_NAME, PEER_CLUSTER) AS T JOIN (SELECT PEER_CLUSTER, MEDIAN(AVVIKELSE_PCT) AS CLUSTER_MEDIAN_PCT FROM (SELECT STORE_NAME, PEER_CLUSTER, (SUM(PROGNOS_KVANTITET) - SUM(FAKTISK_SALD)) / NULLIF(SUM(FAKTISK_SALD), 0) AS AVVIKELSE_PCT FROM "V_KAMPANJ_BUTIK_AVVIKELSE" WHERE VECKA_START >= DATE \'2025-10-01\' GROUP BY STORE_NAME, PEER_CLUSTER) AS X GROUP BY PEER_CLUSTER) AS M ON M.PEER_CLUSTER = T.PEER_CLUSTER WHERE T.STORE_NAME IN (\'Grosshallen Västerhamn\', \'Grosshallen Nordstaden\') ORDER BY T.STORE_NAME')
add("What did over-forecasting cost us in margin in Q3 2026 by chain and tactic on the illustrative cost data?",
    'SELECT KEDJA, TAKTIK_TYP, SUM(OVERPROGNOS_KVANTITET) AS OVERPROGNOS_KVANTITET, ROUND(SUM(SVINNKOSTNAD_SEK)) AS SVINNKOSTNAD_SEK, ROUND(SUM(NEDSATTNINGSKOSTNAD_SEK)) AS NEDSATTNINGSKOSTNAD_SEK, ROUND(SUM(MARGINALEFFEKT_SEK)) AS MARGINALEFFEKT_SEK, ROUND(SUM(MARGINALEFFEKT_SEK) / NULLIF((SELECT SUM(MARGINALEFFEKT_SEK) FROM "V_KAMPANJ_MARGINALEFFEKT" WHERE QUARTER_LABEL = \'2026-Q3\'), 0), 4) AS SHARE_OF_TOTAL, MAX(KALLA) AS KALLA FROM "V_KAMPANJ_MARGINALEFFEKT" WHERE QUARTER_LABEL = \'2026-Q3\' GROUP BY KEDJA, TAKTIK_TYP ORDER BY MARGINALEFFEKT_SEK DESC')
add("How is the Q3 2026 over-forecast margin cost split between perishable waste and markdowns?",
    'SELECT FARSKVARA, SUM(OVERPROGNOS_KVANTITET) AS OVERPROGNOS_KVANTITET, ROUND(SUM(SVINNKOSTNAD_SEK)) AS SVINNKOSTNAD_SEK, ROUND(SUM(NEDSATTNINGSKOSTNAD_SEK)) AS NEDSATTNINGSKOSTNAD_SEK, ROUND(SUM(MARGINALEFFEKT_SEK)) AS MARGINALEFFEKT_SEK, ROUND(SUM(SVINNKOSTNAD_SEK) / NULLIF((SELECT SUM(MARGINALEFFEKT_SEK) FROM "V_KAMPANJ_MARGINALEFFEKT" WHERE QUARTER_LABEL = \'2026-Q3\'), 0), 4) AS WASTE_SHARE_OF_TOTAL, MAX(KALLA) AS KALLA FROM "V_KAMPANJ_MARGINALEFFEKT" WHERE QUARTER_LABEL = \'2026-Q3\' GROUP BY FARSKVARA ORDER BY FARSKVARA DESC')
add("What is the quarterly margin cost of over-forecasting by chain since 2025 on the illustrative cost data?",
    'SELECT QUARTER_LABEL, KEDJA, SUM(OVERPROGNOS_KVANTITET) AS OVERPROGNOS_KVANTITET, ROUND(SUM(MARGINALEFFEKT_SEK)) AS MARGINALEFFEKT_SEK, MAX(KALLA) AS KALLA FROM "V_KAMPANJ_MARGINALEFFEKT" WHERE QUARTER_LABEL >= \'2025-Q1\' GROUP BY QUARTER_LABEL, KEDJA ORDER BY QUARTER_LABEL, KEDJA')
add("Which campaigns in the coming weeks are flagged because the chain forecast exceeds CatBoost by more than 15 percent on perishables?",
    'SELECT KAMPANJ_ID, KAMPANJ_NAMN, KEDJA, TAKTIK_TYP, VECKA_LABEL, LEVERANS_FRAN, MIN(DAGAR_TILL_LEVERANS) AS DAGAR_TILL_LEVERANS, SUM(CASE WHEN FLAGGA THEN 1 ELSE 0 END) AS FLAGGADE_ARTIKLAR, COUNT(*) AS ARTIKLAR, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, SUM(SALD_PROGNOS_CATBOOST) AS SALD_PROGNOS_CATBOOST, ROUND(SUM(KOPT_PROGNOS_KEDJAN) / NULLIF(SUM(SALD_PROGNOS_CATBOOST), 0) - 1, 4) AS PROGNOSGAP_PCT, SUM(FORESLAGEN_MINSKNING_KOLLI) AS FORESLAGEN_MINSKNING_KOLLI, ROUND(SUM(SKYDDAD_MARGINAL_SEK)) AS SKYDDAD_MARGINAL_SEK FROM "V_KAMPANJ_KOMMANDE" GROUP BY KAMPANJ_ID, KAMPANJ_NAMN, KEDJA, TAKTIK_TYP, VECKA_LABEL, LEVERANS_FRAN HAVING SUM(CASE WHEN FLAGGA THEN 1 ELSE 0 END) > 0 ORDER BY LEVERANS_FRAN, SKYDDAD_MARGINAL_SEK DESC')
add("How many campaigns and articles per chain and tactic type are planned for weeks 2026-W41 to 2026-W44?",
    'SELECT KEDJA, TAKTIK_TYP, COUNT(*) AS KAMPANJER, SUM(ANTAL_ARTIKLAR) AS ARTIKLAR, MIN(LEVERANS_FRAN) AS FORSTA_LEVERANS, MAX(LEVERANS_FRAN) AS SISTA_LEVERANS FROM "KAMPANJ" WHERE STATUS = \'Planerad\' AND VECKA_LABEL BETWEEN \'2026-W41\' AND \'2026-W44\' GROUP BY KEDJA, TAKTIK_TYP ORDER BY KEDJA, TAKTIK_TYP')
DRAFT = ('SELECT ARTIKEL_ID, ARTIKEL_NAMN, KATEGORI, KOLLI, LAV, KOPT_PROGNOS_KEDJAN, SALD_PROGNOS_CATBOOST, ROUND(PROGNOSGAP_PCT, 4) AS PROGNOSGAP_PCT, FLAGGA, FORESLAGEN_MINSKNING_KOLLI, FORESLAGEN_MINSKNING_KOLLI * KOLLI AS MINSKNING_ENHETER, '
         'ROUND(INKOPSPRIS_SEK, 2) AS INKOPSPRIS_SEK, ROUND(SKYDDAD_MARGINAL_SEK) AS SKYDDAD_MARGINAL_SEK, KALLA FROM "V_KAMPANJ_KOMMANDE" WHERE KAMPANJ_NAMN = \'Äpplen & Päron\' AND VECKA_LABEL = \'2026-W42\' ORDER BY SKYDDAD_MARGINAL_SEK DESC')
add("Draft the order adjustment for the Äpplen & Päron campaign in week 2026-W42 by article.", DRAFT)
add("/orderjustering-utkast Äpplen & Päron 2026-W42", DRAFT, tags=("eval_only", "skill"))
add("What are the totals of the proposed order adjustment for Äpplen & Päron in week 2026-W42?",
    'SELECT KAMPANJ_NAMN, KEDJA, VECKA_LABEL, LEVERANS_FRAN, MIN(DAGAR_TILL_LEVERANS) AS DAGAR_TILL_LEVERANS, COUNT(*) AS ARTIKLAR, SUM(CASE WHEN FLAGGA THEN 1 ELSE 0 END) AS FLAGGADE_ARTIKLAR, SUM(KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, SUM(SALD_PROGNOS_CATBOOST) AS SALD_PROGNOS_CATBOOST, SUM(FORESLAGEN_MINSKNING_KOLLI) AS FORESLAGEN_MINSKNING_KOLLI, SUM(FORESLAGEN_MINSKNING_KOLLI * KOLLI) AS MINSKNING_ENHETER, ROUND(SUM(FORESLAGEN_MINSKNING_KOLLI * KOLLI) / NULLIF(SUM(KOPT_PROGNOS_KEDJAN), 0), 4) AS MINSKNING_PCT, ROUND(SUM(SKYDDAD_MARGINAL_SEK)) AS SKYDDAD_MARGINAL_SEK, MAX(KALLA) AS KALLA FROM "V_KAMPANJ_KOMMANDE" WHERE KAMPANJ_NAMN = \'Äpplen & Päron\' AND VECKA_LABEL = \'2026-W42\' GROUP BY KAMPANJ_NAMN, KEDJA, VECKA_LABEL, LEVERANS_FRAN')
add("Who is the responsible planner and approver for the Äpplen & Päron campaign?",
    'SELECT KAMPANJ_ID, KAMPANJ_NAMN, KEDJA, VECKA_LABEL, LEVERANS_FRAN, LEVERANS_TILL, STATUS, ANSVARIG_PLANERARE, ANTAL_ARTIKLAR FROM "KAMPANJ" WHERE KAMPANJ_NAMN = \'Äpplen & Päron\' ORDER BY LEVERANS_FRAN')
add("What are the packaging units kolli lav and pall for the articles in the Äpplen & Päron campaign?",
    'SELECT A.ARTIKEL_ID, A.ARTIKEL_NAMN, A.KATEGORI, A.VARUMARKE, A.FARSKVARA, A.HALLBARHET_DAGAR, A.ENHET, A.KOLLI, A.LAV, A.PALL FROM "ARTIKEL" AS A JOIN "KAMPANJ_ARTIKEL_VECKA" AS R ON R.ARTIKEL_ID = A.ARTIKEL_ID JOIN "KAMPANJ" AS K ON K.KAMPANJ_ID = R.KAMPANJ_ID WHERE K.KAMPANJ_NAMN = \'Äpplen & Päron\' ORDER BY A.ARTIKEL_NAMN')
add("Which campaigns belong to a category promotion and how did the Sommarpris campaign perform against forecast?",
    'SELECT K.KAMPANJ_NAMN, K.KEDJA, K.VECKA_LABEL, K.TAKTIK_TYP, P.PROMOTION_NAME, SUM(R.FAKTISK_SALD) AS FAKTISK_SALD, SUM(R.KOPT_PROGNOS_KEDJAN) AS KOPT_PROGNOS_KEDJAN, ROUND((SUM(R.KOPT_PROGNOS_KEDJAN) - SUM(R.FAKTISK_SALD)) / NULLIF(SUM(R.FAKTISK_SALD), 0), 4) AS PROGNOSFEL_KEDJAN_PCT FROM "KAMPANJ" AS K JOIN "PROMOTIONS" AS P ON P.PROMOTION_ID = K.PROMOTION_ID JOIN "KAMPANJ_ARTIKEL_VECKA" AS R ON R.KAMPANJ_ID = K.KAMPANJ_ID WHERE R.FAKTISK_SALD IS NOT NULL GROUP BY K.KAMPANJ_NAMN, K.KEDJA, K.VECKA_LABEL, K.TAKTIK_TYP, P.PROMOTION_NAME ORDER BY K.VECKA_LABEL')
add("What is the share of private label articles in the campaigns of each chain in 2026?",
    'SELECT KEDJA, COUNT(*) AS ARTIKEL_VECKOR, SUM(CASE WHEN EGNA_MARKESVAROR THEN 1 ELSE 0 END) AS EMV_ARTIKEL_VECKOR, ROUND(SUM(CASE WHEN EGNA_MARKESVAROR THEN 1.0 ELSE 0 END) / COUNT(*), 4) AS EMV_SHARE, ROUND(SUM(KAMPANJFORSALJNING_SEK)) AS KAMPANJFORSALJNING_SEK FROM "V_KAMPANJRAPPORT" WHERE KALENDER_VECKA_ID >= 202601 AND AR_AVSLUTAD GROUP BY KEDJA ORDER BY KEDJA')
